"use client"

import { Timeline } from "@ui-sdk/react/timeline"
import { useMemo, type ComponentProps } from "react"

import type { AttemptView } from "@/lib/agent-task-types"
import { toTime, type Instant } from "@/lib/time"
import { cn } from "@/lib/utils"
import { AttemptEvent, type AttemptEventOptions } from "@/components/ui/attempt-event"
import { attemptTimelineLabels, type AttemptTimelineLabels } from "@/components/ui/attempt-timeline-labels"
import { Collapsible, CollapsibleIcon, CollapsiblePanel, CollapsibleTrigger } from "@/components/ui/collapsible"
import { useNow } from "@/components/ui/relative-time"

type AttemptTimelineProps = Omit<ComponentProps<typeof Timeline>, "children"> &
  Partial<Omit<AttemptEventOptions, "labels" | "now" | "usageOpen">> & {
    attempts: AttemptView[]
    labels?: Partial<AttemptTimelineLabels>
    /** "Now" for every relative time; one shared clock when left out. */
    now?: Instant
    /** How many of the latest attempts stay visible; older ones collapse behind a toggle. */
    visibleAttempts?: number
    /** Usage tables start collapsed once there are more attempts than this. */
    usageOpenUpTo?: number
  }

// Ids like "T-014-A1" read as "A1" inside their task; anything else is shown whole.
function defaultFormatAttemptId(id: string) {
  return /-(A\d+)$/.exec(id)?.[1] ?? id
}

function AttemptTimeline({
  attempts,
  labels,
  now,
  visibleAttempts = 5,
  usageOpenUpTo = 5,
  formatAttemptId = defaultFormatAttemptId,
  usageLabels,
  formatCurrency,
  renderStatus,
  renderAgent,
  agentAvatars,
  renderThreadLink,
  onOpenThread,
  locale,
  timeZone,
  className,
  ...props
}: AttemptTimelineProps) {
  const text = { ...attemptTimelineLabels, ...labels }
  const current = useNow({ now })
  const ordered = useMemo(
    () =>
      attempts
        .map((attempt, index) => ({ attempt, index }))
        .toSorted((a, b) => toTime(a.attempt.startedAt) - toTime(b.attempt.startedAt) || a.index - b.index)
        .map(({ attempt }) => attempt),
    [attempts],
  )
  const hiddenCount = Math.max(0, ordered.length - Math.max(1, visibleAttempts))
  const options: AttemptEventOptions = {
    labels: text,
    usageLabels,
    formatCurrency,
    formatAttemptId,
    renderStatus,
    renderAgent,
    agentAvatars,
    renderThreadLink,
    onOpenThread,
    now: current,
    locale,
    timeZone,
    usageOpen: ordered.length <= usageOpenUpTo,
  }
  const event = (attempt: AttemptView) => <AttemptEvent key={attempt.id} attempt={attempt} {...options} />

  // The earlier attempts sit in a panel inside the same list, so arrow keys run through every attempt once open.
  const timeline = (
    <Timeline aria-label={text.timeline} className={cn("flex flex-col", className)} {...props}>
      {hiddenCount > 0 && (
        <CollapsiblePanel className="flex flex-col">{ordered.slice(0, hiddenCount).map(event)}</CollapsiblePanel>
      )}
      {ordered.slice(hiddenCount).map(event)}
    </Timeline>
  )

  if (hiddenCount === 0) return <div data-slot="attempt-timeline">{timeline}</div>
  return (
    <Collapsible render={<div data-slot="attempt-timeline" />} className="gap-items">
      <CollapsibleTrigger className="-ms-control-x self-start text-muted-foreground">
        {(state) => (
          <>
            {state.open ? text.hideEarlier(hiddenCount) : text.showEarlier(hiddenCount)}
            <CollapsibleIcon />
          </>
        )}
      </CollapsibleTrigger>
      {timeline}
    </Collapsible>
  )
}

export { AttemptTimeline, defaultFormatAttemptId }
export type { AttemptTimelineProps }

"use client"

import {
  TimelineConnector,
  TimelineDescription,
  TimelineItem,
  TimelineMarker,
  TimelineTime,
  TimelineTitle,
} from "@ui-sdk/react/timeline"
import type { ReactNode } from "react"

import { AttemptStatusPill } from "@/components/ui/task-status"
import type { AgentRef, AttemptStatus, AttemptView } from "@/lib/agent-task-types"
import type { Instant } from "@/lib/time"
import { cn } from "@/lib/utils"
import {
  AttemptBlocker,
  AttemptChecks,
  AttemptCommits,
  AttemptRoute,
  AttemptThread,
  type ThreadRendering,
} from "@/components/ui/attempt-details"
import type { AgentAvatars } from "@/components/ui/agent-avatar"
import type { AttemptTimelineLabels } from "@/components/ui/attempt-timeline-labels"
import { Collapsible, CollapsibleIcon, CollapsiblePanel, CollapsibleTrigger } from "@/components/ui/collapsible"
import { RelativeTime } from "@/components/ui/relative-time"
import { UsageTable, type UsageLabels } from "@/components/ui/usage"

const markerColor: Record<AttemptStatus, string> = {
  dispatching: "border-info bg-background",
  active: "border-info bg-info",
  succeeded: "border-success bg-success",
  failed: "border-destructive bg-destructive",
  cancelled: "border-muted-foreground bg-background",
  superseded: "border-muted-foreground bg-muted-foreground",
  unknown: "border-dashed border-muted-foreground bg-background",
}

interface AttemptEventOptions extends ThreadRendering {
  labels: AttemptTimelineLabels
  usageLabels?: Partial<UsageLabels>
  formatCurrency?: (usd: number) => string
  formatAttemptId: (id: string) => string
  renderStatus?: (attempt: AttemptView) => ReactNode
  renderAgent?: (agent: AgentRef, requested: boolean) => ReactNode
  /** Images, icons or names per provider for the default agent badges. */
  agentAvatars?: AgentAvatars
  now: Instant
  locale?: string
  timeZone?: string
  usageOpen: boolean
}

function AttemptEvent({ attempt, ...options }: AttemptEventOptions & { attempt: AttemptView }) {
  const { labels, formatAttemptId, now, locale, timeZone } = options
  const name = formatAttemptId(attempt.id)
  const kind = labels.kind[attempt.kind] ?? attempt.kind
  const threads = { renderThreadLink: options.renderThreadLink, onOpenThread: options.onOpenThread }
  const forked = attempt.contextMode === "reuse" || attempt.contextMode === "fork"
  const live = attempt.status === "active" || attempt.status === "dispatching"
  const time = { now, locale, timeZone }

  return (
    <TimelineItem
      value={attempt.id}
      status={live ? "current" : undefined}
      data-attempt-status={attempt.status}
      className="group/attempt relative flex gap-items rounded-control pb-group outline-none data-last:pb-0 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
    >
      {/* oxlint-disable-next-line eskais/spacing-tokens -- centres the size-3 marker on the first 20px line */}
      <TimelineMarker className={cn("mt-1 size-3 shrink-0 rounded-full border-2", markerColor[attempt.status])} />
      {/* oxlint-disable-next-line eskais/spacing-tokens -- geometry: runs from under the size-3 marker, centred on it, to the next one */}
      <TimelineConnector className="absolute start-1.25 top-5 bottom-1 w-0.5 bg-border group-data-last/attempt:hidden" />
      <div className="flex min-w-0 flex-1 flex-col gap-items">
        <div className="flex flex-wrap items-center gap-inline">
          <TimelineTitle className="text-sm font-semibold">
            {name} · {kind}
          </TimelineTitle>
          {options.renderStatus ? (
            options.renderStatus(attempt)
          ) : (
            <AttemptStatusPill status={attempt.status} labels={labels.status} />
          )}
        </div>
        <TimelineTime render={<div />} className="flex flex-wrap gap-x-items text-xs text-muted-foreground">
          <span>
            {labels.started} <RelativeTime value={attempt.startedAt} {...time} />
          </span>
          {attempt.endedAt && (
            <span>
              {labels.ended} <RelativeTime value={attempt.endedAt} {...time} />
            </span>
          )}
        </TimelineTime>
        <TimelineDescription className="flex flex-col gap-inline text-sm">
          <AttemptRoute
            attempt={attempt}
            attemptName={name}
            labels={labels}
            renderAgent={options.renderAgent}
            avatars={options.agentAvatars}
          />
          {(attempt.contextMode || attempt.repairOf) && (
            <span className="flex flex-wrap gap-x-inline text-xs text-muted-foreground">
              {attempt.contextMode && (
                <span data-slot="attempt-context" data-mode={attempt.contextMode}>
                  {labels.context[attempt.contextMode]}
                  {forked && attempt.sourceThread && (
                    <>
                      {" "}
                      {labels.from}{" "}
                      <AttemptThread thread={attempt.sourceThread} label={labels.openSourceThread} {...threads} />
                    </>
                  )}
                </span>
              )}
              {attempt.repairOf && (
                <span data-slot="attempt-repair">{labels.repairs(formatAttemptId(attempt.repairOf))}</span>
              )}
            </span>
          )}
          {attempt.reason && <span data-slot="attempt-reason">{attempt.reason}</span>}
        </TimelineDescription>
        {attempt.checks && attempt.checks.length > 0 && <AttemptChecks checks={attempt.checks} labels={labels} />}
        {attempt.commits && attempt.commits.length > 0 && <AttemptCommits commits={attempt.commits} labels={labels} />}
        {attempt.blocker && (
          <AttemptBlocker blocker={attempt.blocker} labels={labels} locale={locale} timeZone={timeZone} />
        )}
        {attempt.thread && (
          <span className="flex flex-wrap items-center gap-x-inline text-sm">
            <span className="text-muted-foreground">{labels.thread}:</span>
            <AttemptThread thread={attempt.thread} label={labels.openThread} {...threads} />
          </span>
        )}
        {attempt.usage && (
          <Collapsible defaultOpen={options.usageOpen}>
            <CollapsibleTrigger aria-label={labels.usageFor(name)} className="-ms-control-x self-start">
              {labels.usage}
              <CollapsibleIcon />
            </CollapsibleTrigger>
            <CollapsiblePanel>
              <UsageTable
                usage={attempt.usage}
                aria-label={labels.usageTable(name)}
                labels={options.usageLabels}
                locale={locale}
                formatCurrency={options.formatCurrency}
              />
            </CollapsiblePanel>
          </Collapsible>
        )}
      </div>
    </TimelineItem>
  )
}

export { AttemptEvent }
export type { AttemptEventOptions }

"use client"

import type { ReactNode } from "react"

import type { AgentAvatars } from "@/components/ui/agent-avatar"
import { AgentBadge } from "@/components/ui/agent-badge"
import { agentDiffers, effectiveAgent, type AgentRef, type AttemptView, type ThreadRef } from "@/lib/agent-task-types"
import { formatInstant, toISO } from "@/lib/time"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Popover, PopoverContent, PopoverTitle, PopoverTrigger } from "@/components/ui/popover"
import type { AttemptTimelineLabels, CheckResult } from "@/components/ui/attempt-timeline-labels"

interface ThreadRendering {
  renderThreadLink?: (thread: ThreadRef) => ReactNode
  onOpenThread?: (thread: ThreadRef) => void
}

function AttemptThread({
  thread,
  label,
  renderThreadLink,
  onOpenThread,
}: ThreadRendering & { thread: ThreadRef; label: (name: string) => string }) {
  if (renderThreadLink) return renderThreadLink(thread)
  const name = thread.title ?? thread.id
  if (!onOpenThread) return <span data-slot="attempt-thread">{name}</span>
  return (
    <Button
      data-slot="attempt-thread"
      variant="link"
      size="sm"
      aria-label={label(name)}
      className="h-auto max-w-full p-0 whitespace-normal"
      onClick={() => onOpenThread(thread)}
    >
      {name}
    </Button>
  )
}

function defaultRenderAgent(agent: AgentRef, requested: boolean, avatars?: AgentAvatars) {
  return (
    <span data-slot="attempt-agent" data-requested={requested || undefined} className="min-w-0">
      <AgentBadge agent={agent} variant="detail" avatars={avatars} />
    </span>
  )
}

interface AttemptRouteProps {
  attempt: AttemptView
  attemptName: string
  labels: AttemptTimelineLabels
  renderAgent?: (agent: AgentRef, requested: boolean) => ReactNode
  /** Used by the default `renderAgent`. */
  avatars?: AgentAvatars
}

function AttemptRoute({ attempt, attemptName, labels, renderAgent: custom, avatars }: AttemptRouteProps) {
  const renderAgent = custom ?? ((agent: AgentRef, requested: boolean) => defaultRenderAgent(agent, requested, avatars))
  const fallbacks = attempt.fallbacks ?? []
  return (
    <div data-slot="attempt-route" className="flex flex-wrap items-center gap-inline">
      {agentDiffers(attempt) && attempt.executed ? (
        <>
          {renderAgent(attempt.configured, true)}
          <span aria-hidden="true" className="text-muted-foreground">
            →
          </span>
          <span className="sr-only">{labels.ranAs}</span>
          {renderAgent(attempt.executed, false)}
        </>
      ) : (
        renderAgent(effectiveAgent(attempt), false)
      )}
      {fallbacks.length > 0 && (
        <Popover>
          <PopoverTrigger
            variant="ghost"
            size="sm"
            aria-label={labels.earlierRoutesFor(fallbacks.length, attemptName)}
            className="h-auto px-inset-chip py-inset-chip text-xs text-muted-foreground"
          >
            {labels.earlierRoutes(fallbacks.length)}
          </PopoverTrigger>
          <PopoverContent>
            <PopoverTitle>{labels.earlierRoutesTitle}</PopoverTitle>
            <ol className="flex flex-col gap-items text-sm">
              {fallbacks.map(({ agent, reason }) => (
                <li key={`${agent.provider}/${agent.model}/${reason}`} className="flex flex-col gap-inline">
                  {renderAgent(agent, true)}
                  <span className="text-muted-foreground">{reason}</span>
                </li>
              ))}
            </ol>
          </PopoverContent>
        </Popover>
      )}
    </div>
  )
}

const checkColor: Record<CheckResult, string> = {
  pass: "text-success",
  fail: "text-destructive",
  not_run: "text-muted-foreground",
}

function AttemptChecks({
  checks,
  labels,
}: {
  checks: NonNullable<AttemptView["checks"]>
  labels: AttemptTimelineLabels
}) {
  return (
    <ul aria-label={labels.checks} data-slot="attempt-checks" className="flex flex-col gap-items text-sm">
      {checks.map((check) => (
        <li key={check.name} data-result={check.result} className="flex flex-wrap gap-x-inline">
          <span className="font-medium">{check.name}</span>
          <span className={checkColor[check.result]}>{labels.check[check.result]}</span>
          {check.note && <span className="text-muted-foreground">{check.note}</span>}
        </li>
      ))}
    </ul>
  )
}

function AttemptCommits({ commits, labels }: { commits: string[]; labels: AttemptTimelineLabels }) {
  return (
    <ul aria-label={labels.commits} data-slot="attempt-commits" className="flex flex-wrap gap-items">
      {commits.map((sha) => (
        <li key={sha}>
          <code title={sha} className="rounded-sm border bg-muted px-inset-chip font-mono text-xs text-foreground">
            {sha.slice(0, 7)}
          </code>
        </li>
      ))}
    </ul>
  )
}

interface AttemptBlockerProps {
  blocker: NonNullable<AttemptView["blocker"]>
  labels: AttemptTimelineLabels
  locale?: string
  timeZone?: string
  className?: string
}

function AttemptBlocker({ blocker, labels, locale, timeZone, className }: AttemptBlockerProps) {
  return (
    <div
      data-slot="attempt-blocker"
      className={cn(
        "flex flex-col gap-inline rounded-control border border-warning/40 bg-warning/10 px-inset-item py-inset-item text-sm",
        className,
      )}
    >
      <span className="font-medium">
        {labels.blocker}: {blocker.kind}
      </span>
      <span>{blocker.summary}</span>
      {blocker.retryAt && (
        <span className="text-xs">
          {labels.retryAt}{" "}
          <time dateTime={toISO(blocker.retryAt)}>{formatInstant(blocker.retryAt, { locale, timeZone })}</time>
        </span>
      )}
    </div>
  )
}

export { AttemptBlocker, AttemptChecks, AttemptCommits, AttemptRoute, AttemptThread, defaultRenderAgent }
export type { AttemptRouteProps, ThreadRendering }
